package com.gamehub.application.controller;
import com.gamehub.application.OperationsService; import java.time.Instant; import com.gamehub.domain.model.ReservationInterval;
public final class ReservationController { private final OperationsService ops; public ReservationController(OperationsService ops){this.ops=ops;} public long reserve(long customer,long station,Instant start,Instant end)throws Exception{ReservationInterval interval=new ReservationInterval(start,end);return ops.reserve(customer,station,interval.start(),interval.end());} public void cancel(long customer,long reservation)throws Exception{ops.cancelReservation(customer,reservation);} }
